trait Reverse {
    fn reverse(self) -> Self;
}

impl Reverse for u32 {
    fn reverse(self) -> Self {
        let mut result = 0;
        let mut n = self;
        while n > 0 {
            result = result * 10 + n % 10;
            n /= 10;
        }
        result
    }
}

struct Factor {
    factor: Int,
    dividend: Int,
}

fn is_prime(n: Int) -> Bool {
    let mut result = true
    let mut f = Factor { factor: 2, dividend: n }
    while f.factor <= f.dividend {
        if f.factor % f.dividend == 0 {
            result = false
            break
        } else {
            f = Factor { factor: f.factor + 1, dividend: f.dividend }
        }
    }
    result
}

