fn find_duplicates(word: &Str) -> Vec<Str> {
    let mut seen = Vec()
    let mut dupes = Vec()
    for c in chars(&word) {
        if seen.contains(&c) {
            dupes = push(dupes, c)
        } else {
            seen = push(seen, c)
        }
    }
    dupes
}

